import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const v of Object.values(value)) freeze(v);
    Object.freeze(value);
  }
  return value;
}

test('partial overrides merge at multiple levels without changing either input', () => {
  const defaults = freeze({ server: { host: 'localhost', port: 8080, tls: { enabled: true, credentials: { key: 'old', cert: 'keep' } } }, level: 'info' });
  const overrides = freeze({ server: { port: 9090, tls: { credentials: { key: 'new' } } }, extra: { enabled: true } });
  const beforeDefaults = structuredClone(defaults);
  const beforeOverrides = structuredClone(overrides);
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', port: 9090, tls: { enabled: true, credentials: { key: 'new', cert: 'keep' } } },
    level: 'info', extra: { enabled: true }
  });
  assert.deepEqual(defaults, beforeDefaults);
  assert.deepEqual(overrides, beforeOverrides);
});

test('empty nested overrides preserve defaults and newly added keys survive', () => {
  assert.deepEqual(mergeConfig({ a: { b: { c: 1 }, d: 2 } }, { a: { b: {}, e: 3 } }), { a: { b: { c: 1 }, d: 2, e: 3 } });
});

test('recursion is not limited to a few levels', () => {
  let defaults = { keep: 'yes', replace: 1 };
  let overrides = { replace: 2, added: true };
  let expected = { keep: 'yes', replace: 2, added: true };
  for (let i = 0; i < 40; i++) {
    defaults = { next: defaults, sibling: i };
    overrides = { next: overrides };
    expected = { next: expected, sibling: i };
  }
  assert.deepEqual(mergeConfig(defaults, overrides), expected);
});

test('null-prototype plain records merge as records', () => {
  const defaults = { record: Object.assign(Object.create(null), { keep: 1, change: 2 }) };
  const overrides = { record: Object.assign(Object.create(null), { change: 3 }) };
  const result = mergeConfig(defaults, overrides);
  assert.equal(result.record.keep, 1);
  assert.equal(result.record.change, 3);
  assert.deepEqual(Object.keys(result.record).sort(), ['change', 'keep']);
});

test('nested non-object overrides still replace whole subtrees', () => {
  const defaults = { box: { keep: 1, list: ['a', 'b'], nullable: { x: 1 }, scalar: { x: 2 } } };
  const overrides = { box: { list: ['c'], nullable: null, scalar: 7 } };
  assert.deepEqual(mergeConfig(defaults, overrides), { box: { keep: 1, list: ['c'], nullable: null, scalar: 7 } });
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

test('flat merge preserves unspecified keys and accepts new keys', () => {
  const defaults = Object.freeze({ level: 'info', color: true });
  const overrides = Object.freeze({ level: 'debug', file: 'app.log' });
  assert.deepEqual(mergeConfig(defaults, overrides), { level: 'debug', color: true, file: 'app.log' });
  assert.deepEqual(mergeConfig(defaults, {}), defaults);
  assert.deepEqual(mergeConfig({}, overrides), overrides);
});

test('non-plain override values replace whole, including falsy values', () => {
  class Record { constructor() { this.value = 3; } }
  for (const value of [Object.freeze(['c']), null, 'text', '', 0, 42, false, true, undefined, new Date(0), new Record()]) {
    const defaults = Object.freeze({ entry: Object.freeze({ retained: 1 }), other: 2 });
    const overrides = Object.freeze({ entry: value });
    const result = mergeConfig(defaults, overrides);
    assert.equal(result.entry, value);
    assert.equal(result.other, 2);
    assert.ok(Object.hasOwn(result, 'entry'));
    assert.equal(defaults.entry.retained, 1);
    assert.equal(overrides.entry, value);
  }
  assert.deepEqual(mergeConfig({ tags: ['a', 'b'] }, { tags: ['c'] }), { tags: ['c'] });
});

test('a plain object override replaces a non-plain default rather than merging it', () => {
  class Record { constructor() { this.old = true; } }
  for (const value of [null, undefined, 'abc', 3, false, ['a', 'b'], new Date(0), new Record()]) {
    const override = Object.freeze({ added: 1 });
    assert.deepEqual(mergeConfig({ entry: value }, { entry: override }), { entry: { added: 1 } });
  }
});
